//go:build integration

package integration

// Literals repeated across several test files in this package. They live here
// rather than in one of the test files because no single file owns them, and
// goconst flags a string reused three or more times across the package.
const (
	// windowsGOOS matches runtime.GOOS on Windows, where the shell-script and
	// PATH-plugin harnesses do not run.
	windowsGOOS = "windows"

	// contentV1/V2/V3 are successive file contents used by the rewind and
	// resume tests to prove a checkpoint restored the expected revision.
	contentV1 = "version 1"
	contentV2 = "version 2"
	contentV3 = "version 3"

	// preservedSetting is the sentinel value the hook-installation tests write
	// into an agent's existing settings file to prove installation merges into
	// it rather than clobbering it.
	preservedSetting = "should-be-preserved"
)

