26	// writePluginScript writes a shell script that records argv and exits
27	// with exitCode. Skips the calling test on Windows.
28	func writePluginScript(t *testing.T, dir, binaryName, argFile string, exitCode int) {
29		t.Helper()
30		if runtime.GOOS == windowsGOOS {
31			t.Skip("plugin shell-script harness only runs on Unix")
32		}
33		path := filepath.Join(dir, binaryName)
34		body := fmt.Sprintf(
35			"#!/bin/sh\nprintf '%%s\\n' \"$@\" > %q\n"+
36				"echo \"plugin stdout\"\n"+
37				"echo \"plugin stderr\" 1>&2\n"+
38				"exit %d\n",
39			argFile, exitCode,
40		)
41		if err := os.WriteFile(path, []byte(body), 0o755); err != nil {
42			t.Fatalf("write plugin %s: %v", path, err)
43		}
44	}
45	
46	// pathWith returns os.Environ with dir prepended to PATH. Returning a
47	// fresh env slice (rather than t.Setenv) keeps tests parallel-safe.
48	func pathWith(dir string) []string {
49		env := os.Environ()
50		for i, kv := range env {
51			if strings.HasPrefix(kv, "PATH=") {
52				env[i] = "PATH=" + dir + string(os.PathListSeparator) + strings.TrimPrefix(kv, "PATH=")
53				return env
54			}
55		}
56		return append(env, "PATH="+dir)
57	}
