package integration

// Literals repeated across several test files in this package. They live here
// rather than in one of the test files because no single file owns them, and
// goconst flags a string reused three or more times across the package.
const (
	// windowsGOOS matches runtime.GOOS on Windows, where the shell-script and
	// PATH-plugin harnesses do not run.
	windowsGOOS = "windows"

	// contentV1/V2/V3 are successive file contents used by the rewind and
	// resume tests to prove a checkpoint restored the expected revision.
	contentV1 = "version 1"
	contentV2 = "version 2"
	contentV3 = "version 3"

	// preservedSetting is the sentinel value the hook-installation tests write
	// into an agent's existing settings file to prove installation merges into
	// it rather than clobbering it.
	preservedSetting = "should-be-preserved"

	// pkgFuncA/pkgFuncB are throwaway Go file bodies used as agent-written
	// content wherever a test needs two distinguishable committed files.
	pkgFuncA = "package main\n\nfunc A() {}\n"
	pkgFuncB = "package main\n\nfunc B() {}\n"

	// Device-flow endpoints served by the fake OAuth server in the login and
	// trail-resume tests.
	pathDeviceAuthorization = "/device_authorization"
	pathOAuthToken          = "/oauth/token"

	// agentClaudeCode is the agent name these tests enable and assert on. It
	// mirrors agent.AgentNameClaudeCode, which is a types.AgentName rather than
	// a plain string, so it cannot be used directly where a string is wanted.
	agentClaudeCode = "claude-code"

	// testSessionID is the fixed session ID used by tests that only need one
	// session and assert on it by name.
	testSessionID = "test-session"
)

