package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	names := []string{"windowsGOOS", "contentV1", "contentV2", "contentV3", "preservedSetting",
		"pkgFuncA", "pkgFuncB", "pathDeviceAuthorization", "pathOAuthToken", "agentClaudeCode",
		"testSessionID", "rubyHello", "rubyPuts", "reviewSkillPR", "sha256HexLen"}
	fset := token.NewFileSet()
	_ = filepath.Walk(".", func(p string, i os.FileInfo, e error) error {
		if e != nil || i.IsDir() || !strings.HasSuffix(p, ".go") || strings.Contains(p, "/vendor/") {
			return nil
		}
		f, err := parser.ParseFile(fset, p, nil, parser.SkipObjectResolution)
		if err != nil {
			return nil
		}
		ast.Inspect(f, func(n ast.Node) bool {
			lit, ok := n.(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			for _, nm := range names {
				if strings.Contains(lit.Value, nm) {
					fmt.Printf("%s: string literal contains %q\n", fset.Position(lit.Pos()), nm)
				}
			}
			return true
		})
		return nil
	})
}
